def breaking_records(scores: list[int]) -> list[int]:
    min_s = max_s = scores[0]
    c_min = c_max = 0
    for s in scores[1:]:
        if s > max_s:
            max_s = s
            c_max += 1
        elif s < min_s:
            min_s = s
            c_min += 1
    return [c_max, c_min]
